import * as THREE from 'three';

export type SaddleMountTarget = 'horse' | 'catlion' | 'stag';

export interface SaddleMountPreset {
  scale: [number, number, number];
  backY: number;
  backZ: number;
  pitchDeg: number;
  archLift: number;
  rockerLift: number;
  flankFlare: number;
  joints: [number, number, number]; // [rearSpine, midSpine, frontWithers]
}

export const SADDLE_MOUNT_PRESETS: Record<SaddleMountTarget, SaddleMountPreset> = {
  horse: {
    scale: [1.20, 0.92, 0.82],
    backY: 1.326,
    backZ: -0.17,
    pitchDeg: -1.0,
    archLift: 0.068,
    rockerLift: 0.028,
    flankFlare: 0.055,
    joints: [8, 19, 22],
  },
  catlion: {
    scale: [1.34, 1.05, 0.78],
    backY: 1.028,
    backZ: -0.16,
    pitchDeg: -5.0,
    archLift: 0.065,
    rockerLift: 0.022,
    flankFlare: 0.085,
    joints: [3, 4, 5],
  },
  stag: {
    scale: [0.78, 0.70, 0.58],
    backY: 0.968,
    backZ: -0.16,
    pitchDeg: -2.5,
    archLift: 0.042,
    rockerLift: 0.020,
    flankFlare: 0.040,
    joints: [4, 5, 6],
  },
};

export interface SaddleOptions {
  scale?: number;
  castShadow?: boolean;
  receiveShadow?: boolean;
  tintHex?: number;
  wireframe?: boolean;
}

export interface UnpackedSaddleData {
  positions: Float32Array;
  normals: Float32Array;
  uvs: Float32Array;
  indices: Uint16Array;
}

const NUM_VERTS = 1941;
const NUM_INDICES = 7290;

export function unpackSaddleBundle(b64: string): UnpackedSaddleData {
  const binStr = atob(b64);
  const len = binStr.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  const buf = bytes.buffer;
  let off = 0;

  const posI16 = new Int16Array(buf, off, NUM_VERTS * 3);
  off += NUM_VERTS * 3 * 2;
  const positions = new Float32Array(NUM_VERTS * 3);
  for (let i = 0; i < positions.length; i++) {
    positions[i] = posI16[i] / 8000.0;
  }

  const normalsI8 = new Int8Array(buf, off, NUM_VERTS * 3);
  off = (off + NUM_VERTS * 3 + 3) & ~3;
  const normals = new Float32Array(NUM_VERTS * 3);
  for (let i = 0; i < normals.length; i++) {
    normals[i] = normalsI8[i] / 127.0;
  }

  const uvsU16 = new Uint16Array(buf, off, NUM_VERTS * 2);
  off += NUM_VERTS * 2 * 2;
  const uvs = new Float32Array(NUM_VERTS * 2);
  for (let i = 0; i < uvs.length; i++) {
    uvs[i] = uvsU16[i] / 65535.0;
  }

  const indices = new Uint16Array(buf, off, NUM_INDICES);

  return {
    positions,
    normals,
    uvs,
    indices,
  };
}

export function createSkinnedSaddleMesh(
  data: UnpackedSaddleData,
  texture: THREE.Texture,
  skeleton: THREE.Skeleton,
  target: SaddleMountTarget | SaddleMountPreset,
  options: SaddleOptions = {},
): THREE.SkinnedMesh {
  const preset = typeof target === 'string' ? SADDLE_MOUNT_PRESETS[target] : target;
  const [sx, sy, sz] = preset.scale;
  const pitchRad = THREE.MathUtils.degToRad(preset.pitchDeg);
  const cosP = Math.cos(pitchRad);
  const sinP = Math.sin(pitchRad);
  const [jRear, jMid, jFront] = preset.joints;
  const archLift = preset.archLift ?? 0.065;
  const rockerLift = preset.rockerLift ?? 0.025;
  const flankFlare = preset.flankFlare ?? 0.055;

  const pos = new Float32Array(NUM_VERTS * 3);
  const skinIndices = new Uint8Array(NUM_VERTS * 4);
  const skinWeights = new Float32Array(NUM_VERTS * 4);

  for (let i = 0; i < NUM_VERTS; i++) {
    const i3 = i * 3;
    const i4 = i * 4;
    const x = data.positions[i3];
    const y = data.positions[i3 + 1];
    const z = data.positions[i3 + 2];

    const yRel = y - 0.743;
    const ux = Math.min(1.35, Math.abs(x) / 0.22);
    const uz = Math.min(1.25, Math.abs(z) / 0.45);
    const wUpper = Math.max(0.0, Math.min(1.0, (yRel + 0.35) / 0.35));
    const wFlank = Math.max(0.0, Math.min(1.0, (0.15 - yRel) / 0.35)) * Math.max(0.0, Math.min(1.0, (yRel + 0.78) / 0.20));
    const xSgn = x >= 0 ? 1.0 : -1.0;

    const x1 = x * sx + xSgn * flankFlare * Math.pow(ux, 1.1) * wFlank;
    const y1 = yRel * sy + archLift * Math.pow(ux, 1.5) * wUpper + rockerLift * (uz * uz) * wUpper;
    const z1 = z * sz;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    pos[i3] = x1;
    pos[i3 + 1] = preset.backY + y2;
    pos[i3 + 2] = preset.backZ + z2;

    const u = Math.max(-1.0, Math.min(1.0, z / 0.45));
    let wRear = 0.0;
    let wFront = 0.0;
    if (u < 0) {
      wRear = Math.min(0.65, -u * 0.65);
    } else {
      wFront = Math.min(0.65, u * 0.65);
    }
    const wMid = 1.0 - wRear - wFront;

    skinIndices[i4] = jMid;
    skinIndices[i4 + 1] = jFront;
    skinIndices[i4 + 2] = jRear;
    skinIndices[i4 + 3] = 0;

    skinWeights[i4] = wMid;
    skinWeights[i4 + 1] = wFront;
    skinWeights[i4 + 2] = wRear;
    skinWeights[i4 + 3] = 0.0;
  }

  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geom.setAttribute('normal', new THREE.BufferAttribute(data.normals.slice(), 3));
  geom.setAttribute('uv', new THREE.BufferAttribute(data.uvs, 2));
  geom.setAttribute('skinIndex', new THREE.Uint8BufferAttribute(skinIndices, 4));
  geom.setAttribute('skinWeight', new THREE.Float32BufferAttribute(skinWeights, 4));
  geom.setIndex(new THREE.BufferAttribute(data.indices, 1));

  texture.flipY = false;
  texture.needsUpdate = true;

  const mat = new THREE.MeshStandardMaterial({
    map: texture,
    color: options.tintHex ?? 0xffffff,
    roughness: 0.76,
    metalness: 0.08,
    side: THREE.DoubleSide,
    wireframe: options.wireframe ?? false,
  });

  const mesh = new THREE.SkinnedMesh(geom, mat);
  mesh.name = 'MountedSaddle';
  mesh.castShadow = options.castShadow ?? true;
  mesh.receiveShadow = options.receiveShadow ?? true;
  mesh.frustumCulled = false;
  mesh.bind(skeleton, new THREE.Matrix4());
  return mesh;
}

export class Saddle {
  public readonly object: THREE.Group;
  public readonly mesh: THREE.Mesh;
  public readonly data: UnpackedSaddleData;
  public readonly texture: THREE.Texture;

  constructor(data: UnpackedSaddleData, texture: THREE.Texture, options: SaddleOptions = {}) {
    const scale = options.scale ?? 1.0;
    const castShadow = options.castShadow ?? true;
    const receiveShadow = options.receiveShadow ?? true;

    this.data = data;
    this.texture = texture;
    this.object = new THREE.Group();
    this.object.name = 'Saddle';

    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(data.positions, 3));
    geom.setAttribute('normal', new THREE.BufferAttribute(data.normals, 3));
    geom.setAttribute('uv', new THREE.BufferAttribute(data.uvs, 2));
    geom.setIndex(new THREE.BufferAttribute(data.indices, 1));

    texture.flipY = false;
    texture.needsUpdate = true;

    const mat = new THREE.MeshStandardMaterial({
      map: texture,
      color: options.tintHex ?? 0xffffff,
      roughness: 0.76,
      metalness: 0.08,
      side: THREE.DoubleSide,
      wireframe: options.wireframe ?? false,
    });

    this.mesh = new THREE.Mesh(geom, mat);
    this.mesh.castShadow = castShadow;
    this.mesh.receiveShadow = receiveShadow;
    this.object.add(this.mesh);
    this.object.scale.setScalar(scale);
  }

  public mountOnCreature(
    creature: { object: THREE.Group; rig: { skeleton: THREE.Skeleton } },
    target: SaddleMountTarget | SaddleMountPreset,
    options: SaddleOptions = {},
  ): THREE.SkinnedMesh {
    const skinnedSaddle = createSkinnedSaddleMesh(this.data, this.texture, creature.rig.skeleton, target, options);
    creature.object.add(skinnedSaddle);
    return skinnedSaddle;
  }

  public dispose(): void {
    this.mesh.geometry.dispose();
    if (Array.isArray(this.mesh.material)) {
      this.mesh.material.forEach((m) => m.dispose());
    } else {
      this.mesh.material.dispose();
    }
  }
}

export function createSaddle(
  b64Data: string,
  texture: THREE.Texture,
  options: SaddleOptions = {},
): Saddle {
  const data = unpackSaddleBundle(b64Data);
  return new Saddle(data, texture, options);
}

export const SADDLE_PACK_B64 = "";
export const SADDLE_TEX_B64 = "data:image/jpeg;base64,";
let cachedSaddleData: UnpackedSaddleData | null = null;
let cachedSaddleTexture: THREE.Texture | null = null;

function getReadySaddleAssets(): { data: UnpackedSaddleData; texture: THREE.Texture } {
  if (!cachedSaddleData) {
    cachedSaddleData = unpackSaddleBundle(SADDLE_PACK_B64);
  }
  if (!cachedSaddleTexture) {
    if (typeof Image !== 'undefined') {
      const img = new Image();
      img.src = SADDLE_TEX_B64;
      const tex = new THREE.Texture(img);
      tex.flipY = false;
      tex.colorSpace = THREE.SRGBColorSpace;
      img.onload = () => {
        tex.needsUpdate = true;
      };
      cachedSaddleTexture = tex;
    } else {
      const tex = new THREE.DataTexture(new Uint8Array([122, 80, 48, 255]), 1, 1);
      tex.flipY = false;
      tex.needsUpdate = true;
      cachedSaddleTexture = tex;
    }
  }
  return { data: cachedSaddleData, texture: cachedSaddleTexture };
}

export function createStandaloneSaddle(options: SaddleOptions = {}): Saddle {
  const { data, texture } = getReadySaddleAssets();
  return new Saddle(data, texture, options);
}

export function createReadySaddle(options: SaddleOptions = {}): Saddle {
  return createStandaloneSaddle(options);
}

export function mountReadySaddleOnCreature(
  creature: { object: THREE.Group; rig: { skeleton: THREE.Skeleton } },
  target: SaddleMountTarget | SaddleMountPreset,
  options: SaddleOptions = {},
): THREE.SkinnedMesh {
  const { data, texture } = getReadySaddleAssets();
  const skinnedSaddle = createSkinnedSaddleMesh(data, texture, creature.rig.skeleton, target, options);
  creature.object.add(skinnedSaddle);
  return skinnedSaddle;
}
